    <div class="hover-preview" id="hover-preview" hidden>
      <p class="attack-preview building-preview" id="building-preview" tabindex="0" role="status" aria-live="polite" hidden><span class="preview-value" aria-hidden="true"></span><span class="sr-only"></span></p>
    </div>
